definition.script:
pipeline {
    agent any
    stages {
        stage('Test') {
            steps {
                writeFile file: 'results.xml', text: '''<testsuite name="e2e.Suite" tests="4" failures="1" skipped="1">
  <testcase classname="e2e.Suite" name="test_passes" time="0.1"/>
  <testcase classname="e2e.Suite" name="test_also_passes" time="0.2"/>
  <testcase classname="e2e.Suite" name="test_fails" time="0.3">
    <failure message="e2e-expected-failure">e2e-expected-failure</failure>
  </testcase>
  <testcase classname="e2e.Suite" name="test_skipped"><skipped/></testcase>
</testsuite>'''
                junit 'results.xml'
            }
        }
    }
}
